INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 27, 'theory', 'Quiz: I/O');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 0, 'Why wrap a file in a BufReader for line-by-line reading?', '["to get lines(), which File itself does not have, and to cut the number of system calls", "to read faster without buffers", "so that the file is closed by hand", "to read only bytes"]', 0, 'BufReader reads in big blocks: fewer system calls; BufRead adds read_line and lines().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 1, 'What does read return when the end of the stream is reached?', '["Err(UnexpectedEof)", "None", "Ok(0)", "a panic"]', 2, 'Ok(0) means end of stream; read_exact in that situation returns an UnexpectedEof error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 2, 'What is the simplest way to test a function that reads from R: BufRead?', '["create a temporary file and read it", "pass Cursor::new(\"…\"), data in memory", "it can''t be done, you need a real stdin", "override stdin globally"]', 1, 'Cursor implements Read and BufRead: tests never touch the disk.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 3, 'How does Path differ from PathBuf?', '["Path is for Windows, PathBuf is for Linux", "they don''t differ", "Path can''t be printed", "Path is a reference (like &str), PathBuf is owning (like String)"]', 3, 'They don''t have to be Unicode; to print, use path.display().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 4, 'What does flush do?', '["closes the file", "pushes buffered data through to the sink", "clears the contents of the file", "nothing, it is an empty method"]', 1, 'After print! without a newline you need flush(), otherwise the prompt may not appear; BufWriter also flushes its buffer on drop.');
